//! Pinned FFT input transport for Tidewater. Render targets are generated by Bevy.
use forge_core::{ContentHash, bytes_sha256};
use serde::Deserialize;
use std::collections::{BTreeMap, BTreeSet};

const COMMIT: &str = "1438b1abfcaee3267092b75573014f4d9b4a983c";
const KERNELS: [&str; 9] = [
    "initSpectrum",
    "conjugate",
    "copyH0",
    "row",
    "column",
    "mipA-0",
    "mipA-1",
    "mipB-0",
    "mipB-1",
];

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Entry {
    sha256: ContentHash,
    bytes: usize,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Manifest {
    schema: String,
    version: u32,
    source_commit: String,
    source_bundle_sha256: ContentHash,
    files: BTreeMap<String, Entry>,
}

/// Source shaders and uniforms for the four-cascade 256² FFT.
/// No baked displacement, derivative or foam result is accepted.
#[derive(Debug)]
pub struct OceanPackage {
    files: BTreeMap<String, Vec<u8>>,
    source_bundle_sha256: ContentHash,
}

impl OceanPackage {
    /// Load bounded bytes from a filesystem or another synchronous transport.
    pub fn load(
        manifest: &[u8],
        expected: ContentHash,
        mut read: impl FnMut(&str, usize) -> Result<Vec<u8>, String>,
    ) -> Result<Self, String> {
        let metadata = parse(manifest, expected)?;
        let mut files = BTreeMap::new();
        for (name, entry) in metadata.files {
            let bytes = read(&name, entry.bytes)?;
            verify(&entry, &bytes)?;
            files.insert(name, bytes);
        }
        verify_inner(&files)?;
        Ok(Self {
            files,
            source_bundle_sha256: metadata.source_bundle_sha256,
        })
    }

    /// Load through the sequential browser transport used by Studio.
    pub async fn load_async<F, Fut>(
        manifest: &[u8],
        expected: ContentHash,
        mut read: F,
    ) -> Result<Self, String>
    where
        F: FnMut(String, usize) -> Fut,
        Fut: std::future::Future<Output = Result<Vec<u8>, String>>,
    {
        let metadata = parse(manifest, expected)?;
        let mut files = BTreeMap::new();
        for (name, entry) in metadata.files {
            let bytes = read(name.clone(), entry.bytes).await?;
            verify(&entry, &bytes)?;
            files.insert(name, bytes);
        }
        verify_inner(&files)?;
        Ok(Self {
            files,
            source_bundle_sha256: metadata.source_bundle_sha256,
        })
    }

    #[must_use]
    pub fn file(&self, name: &str) -> Option<&[u8]> {
        self.files.get(name).map(Vec::as_slice)
    }

    #[must_use]
    pub fn source_bundle_sha256(&self) -> ContentHash {
        self.source_bundle_sha256
    }
}

fn required() -> BTreeSet<String> {
    let mut names: BTreeSet<_> = [
        "ocean.json",
        "params-initial.bin",
        "frame-120-frame.bin",
        "frame-120-params.bin",
        "LICENSE-Tidewater.txt",
    ]
    .into_iter()
    .map(str::to_owned)
    .collect();
    names.extend(KERNELS.map(|name| format!("{name}.wgsl")));
    names
}

fn parse(bytes: &[u8], expected: ContentHash) -> Result<Manifest, String> {
    if bytes.len() > 8 * 1024 || bytes_sha256(bytes) != expected {
        return Err("Ocean manifest pin mismatch or size limit".into());
    }
    let manifest: Manifest = serde_json::from_slice(bytes).map_err(|e| e.to_string())?;
    if manifest.schema != "forge.tidewater.ocean-input-package"
        || manifest.version != 1
        || manifest.source_commit != COMMIT
        || manifest.files.keys().cloned().collect::<BTreeSet<_>>() != required()
    {
        return Err("Unsupported or incomplete ocean input package".into());
    }
    let mut total = 0_usize;
    for entry in manifest.files.values() {
        if entry.bytes == 0 || entry.bytes > 64 * 1024 {
            return Err("Ocean input payload size limit".into());
        }
        total = total
            .checked_add(entry.bytes)
            .ok_or("Ocean input size overflow")?;
    }
    if total > 256 * 1024 {
        return Err("Ocean input package size limit".into());
    }
    Ok(manifest)
}

fn verify(entry: &Entry, bytes: &[u8]) -> Result<(), String> {
    if bytes.len() != entry.bytes || bytes_sha256(bytes) != entry.sha256 {
        return Err("Ocean input size or pin mismatch".into());
    }
    Ok(())
}

fn verify_inner(files: &BTreeMap<String, Vec<u8>>) -> Result<(), String> {
    let metadata: serde_json::Value =
        serde_json::from_slice(&files["ocean.json"]).map_err(|error| error.to_string())?;
    if metadata["schema"] != "forge.tidewater.ocean-probe"
        || metadata["version"] != 1
        || metadata["source_commit"] != COMMIT
        || metadata["fft_size"] != 256
        || metadata["cascades"] != 4
    {
        return Err("Ocean source metadata mismatch".into());
    }
    for (name, bytes) in files {
        if name == "ocean.json" || name == "LICENSE-Tidewater.txt" {
            continue;
        }
        let hash = bytes_sha256(bytes).to_string();
        if metadata["files"][name].as_str() != Some(hash.as_str()) {
            return Err(format!("Ocean source metadata pin mismatch: {name}"));
        }
    }
    if files["params-initial.bin"].len() != 224
        || files["frame-120-params.bin"].len() != 224
        || files["frame-120-frame.bin"].len() != 720
        || files["frame-120-frame.bin"][584..588] != (1.0_f32 / 60.0).to_le_bytes()
    {
        return Err("Ocean source uniform layout mismatch".into());
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn inputs() -> BTreeMap<String, Vec<u8>> {
        let mut files = BTreeMap::new();
        let mut frame = vec![0; 720];
        frame[584..588].copy_from_slice(&(1.0_f32 / 60.0).to_le_bytes());
        files.insert("frame-120-frame.bin".into(), frame);
        files.insert("frame-120-params.bin".into(), vec![0; 224]);
        files.insert("params-initial.bin".into(), vec![0; 224]);
        files.insert("LICENSE-Tidewater.txt".into(), b"MIT License".to_vec());
        for name in KERNELS {
            files.insert(format!("{name}.wgsl"), b"@compute fn main() {}".to_vec());
        }
        let pinned: BTreeMap<_, _> = files
            .iter()
            .filter(|(name, _)| name.as_str() != "LICENSE-Tidewater.txt")
            .map(|(name, bytes)| (name.clone(), bytes_sha256(bytes).to_string()))
            .collect();
        files.insert(
            "ocean.json".into(),
            serde_json::to_vec(&json!({
                "schema":"forge.tidewater.ocean-probe", "version":1,
                "source_commit":COMMIT, "fft_size":256, "cascades":4,
                "files":pinned
            }))
            .unwrap(),
        );
        files
    }

    fn manifest(files: &BTreeMap<String, Vec<u8>>) -> Vec<u8> {
        let entries: BTreeMap<_, _> = files
            .iter()
            .map(|(name, bytes)| {
                (
                    name.clone(),
                    json!({"sha256":bytes_sha256(bytes), "bytes":bytes.len()}),
                )
            })
            .collect();
        serde_json::to_vec(&json!({
            "schema":"forge.tidewater.ocean-input-package", "version":1,
            "source_commit":COMMIT,
            "source_bundle_sha256":bytes_sha256(b"pinned source bundle"),
            "files":entries
        }))
        .unwrap()
    }

    #[test]
    fn pinned_inputs_reject_regenerated_outer_pin_with_stale_source_metadata() {
        let mut files = inputs();
        let bytes = manifest(&files);
        let hash = bytes_sha256(&bytes);
        let package = OceanPackage::load(&bytes, hash, |name, _| Ok(files[name].clone())).unwrap();
        assert_eq!(package.file("params-initial.bin").unwrap().len(), 224);
        assert_eq!(
            package.source_bundle_sha256(),
            bytes_sha256(b"pinned source bundle")
        );

        files.get_mut("params-initial.bin").unwrap()[0] = 1;
        let bytes = manifest(&files);
        let hash = bytes_sha256(&bytes);
        assert!(
            OceanPackage::load(&bytes, hash, |name, _| Ok(files[name].clone()))
                .unwrap_err()
                .contains("source metadata pin mismatch")
        );

        files.insert("displacement-m0.rgba16.bin".into(), vec![1]);
        let bytes = manifest(&files);
        let hash = bytes_sha256(&bytes);
        assert!(
            OceanPackage::load(&bytes, hash, |name, _| Ok(files[name].clone()))
                .unwrap_err()
                .contains("incomplete ocean input package")
        );
    }

    #[test]
    #[ignore = "requires the locally acquired Tidewater ocean package"]
    fn acquired_fft_inputs_match_both_manifests() {
        let root = std::path::PathBuf::from(
            std::env::var("FORGE_TIDEWATER_OCEAN_PACKAGE")
                .expect("set FORGE_TIDEWATER_OCEAN_PACKAGE to the acquired package directory"),
        );
        let manifest = std::fs::read(root.join("package.json")).unwrap();
        let hash = bytes_sha256(&manifest);
        let package = OceanPackage::load(&manifest, hash, |name, _| {
            std::fs::read(root.join(name)).map_err(|error| error.to_string())
        })
        .unwrap();
        assert_eq!(
            package.source_bundle_sha256(),
            ContentHash::parse("c739c737914261991fd9aba21c4372e7e9cafa31527f7a4139001a4db8e9b335")
                .unwrap()
        );
        assert!(package.file("column.wgsl").unwrap().len() > 10_000);
    }
}
